+    ),
+    transportFactory: factory.call,
+  );
+
+  FakeMcpServerFactory pingFactory() =>
+      FakeMcpServerFactory()
+        ..onSpawn = (server) {
+          server.tools = [
+            {'name': 'ping', 'description': 'pings things'},
+          ];
+        };
+
