+        final lines = io.out.toString().split('\n');
+        for (final id in knownToolIds) {
+          final on = piToolIds.contains(id);
+          final prefix = '${id.padRight(16)} ';
+          final line = lines.firstWhere(
+            (l) => l.startsWith(prefix),
+            orElse: () => '',
