+        );
+        final run = cli.run();
+        // The fake server connects and reports its tools to the manager —
+        // the refilter (pi branch) must still keep them off the registry.
+        await waitForIt(
+          () => (cli.mcpManagerForTest?.tools ?? const []).isNotEmpty,
