/// Re-registers the MCP tool surface and rebuilds the prompt whenever a
/// server connects, fails, or drops.
void _onMcpChanged() {
  _mcp.reRegister(_toolRegistry, _agent, _applyPromptComposition);
  // Re-apply the availability decision to the fresh MCP surface (a
  // no-op until the first rebuild produced a resolution).
  final resolution = _toolGate.resolution;
  if (resolution != null) {
    AgentCliTools(this).refilterMcpTools(resolution);
  }
}


/// The cached `<memory>` prompt section (durable facts from past
/// sessions). Loaded asynchronously after startup and refreshed on
/// every `memory_add` — the prompt composition itself stays
/// synchronous; the composition code lives in agent_cli_prompt.dart.
var _memorySection = '';

/// Reference to the active TUI controller so asynchronous model-list updates
/// can refresh the picker while it is open.
void _swapReadSqliteVariant(ToolAvailabilityResolution resolution) {
  final wantSqlite = resolution.byId['sqlite']?.enabled ?? false;
  final group = _toolGroupsById['read'];
  if (group == null || group.isEmpty) return;
  final hasSqlite = group.first.description.contains(readSqliteSectionPrompt);
  if (wantSqlite == hasSqlite) return;
  final fresh = readFileTool(
    _coreToolEnv,
    snapshots: _snapshotStore,
    model: () => _agent.state.model,
    sqlite: wantSqlite ? config.sqliteEngine : null,
  );
  _toolRegistry.unregister('read');
  _toolRegistry.register(fresh);
  group[0] = fresh;
}

/// Re-filters the dynamic MCP surface against [resolution]: disabled
/// servers get their tools unregistered (and their names noted so the
/// gate tombstones them), re-enabled servers get their tools registered
/// straight from the manager — no server restart (AC13).

