+          reason: 'pi boot print',
+        );
+        expect(
+          cli.agent.state.tools.map((t) => t.name),
+          isNot(contains('mcp__fs__ping')),
+        );
+        io.sendLine('/exit');
+        await run;
+      },
+    );
+
+    test(
+      'the same MCP config registers its tool in default mode (control)',
